"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["793034"],{67680:function(e){e.exports=JSON.parse('{"tag":{"label":"Robotics","permalink":"/tags/robotics","allTagsPath":"/tags","count":12,"items":[{"id":"es/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/es_reComputer_Robotics_Getting_Started","title":"Comenzando con reComputer Robotics","description":"El reComputer Robotics J401 es una placa portadora de IA de borde de alto rendimiento dise\xf1ada para aplicaciones rob\xf3ticas avanzadas. Soporta m\xf3dulos NVIDIA Jetson Orin Nano y Orin NX en modo Super/MAXN, entregando hasta 157 TOPS de potencia de c\xf3mputo de IA. La placa ofrece amplias opciones de conectividad, incluyendo Ethernet Gigabit dual, m\xfaltiples puertos USB 3.2, CAN, ranuras M.2 para m\xf3dulos 5G/Wi-Fi/BT, y soporte opcional para c\xe1maras GMSL2. Pre-instalado con JetPack 6, asegura un despliegue sin problemas para el desarrollo rob\xf3tico. El dise\xf1o robusto soporta amplias temperaturas de operaci\xf3n e incluye un disipador de calor pre-instalado con ventilador. La configuraci\xf3n involucra flashear el SO JetPack en un SSD NVMe usando una PC host Ubuntu compatible, seguido de configuraci\xf3n de hardware y uso de interfaces. Se proporcionan especificaciones detalladas de hardware, dibujos mec\xe1nicos y recursos t\xe9cnicos para desarrolladores, junto con canales de soporte comunitario y t\xe9cnico para resoluci\xf3n de problemas y discusi\xf3n.","permalink":"/es/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/reComputer_Robotics_Getting_Started","title":"Getting Started with reComputer Robotics","description":"The reComputer Robotics J401 is a high-performance edge AI carrier board designed for advanced robotics applications. It supports NVIDIA Jetson Orin Nano and Orin NX modules in Super/MAXN mode, delivering up to 157 TOPS of AI computing power. The board offers extensive connectivity options, including dual Gigabit Ethernet, multiple USB 3.2 ports, CAN, M.2 slots for 5G/Wi-Fi/BT modules, and optional GMSL2 camera support. Pre-installed with JetPack 6, it ensures seamless deployment for robotics development. The rugged design supports wide operating temperatures and includes a pre-installed heatsink with fan. The setup involves flashing the JetPack OS onto an NVMe SSD using a compatible Ubuntu host PC, followed by hardware configuration and interface usage. Detailed hardware specifications, mechanical drawings, and technical resources are provided for developers, along with community and technical support channels for troubleshooting and discussion.","permalink":"/recomputer_robotics_j401_getting_started"},{"id":"es/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/es_reComputer_Robotics_Hardware_Interfaces_Usage","title":"Hardware y Uso de Interfaces de reComputer Robotics","description":"Esta wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y el uso de interfaces de la placa portadora reComputer Jetson Robotics J401. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, UART, I2C y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J401.","permalink":"/es/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_jetson_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/reComputer_Robotics_Hardware_Interfaces_Usage","title":"reComputer Robotics Hardware and Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"zh-CN/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/cn_reComputer_Robotics_Getting_Started","title":"reComputer Robotics \u5165\u95E8\u6307\u5357","description":"reComputer Robotics J401 \u662F\u4E00\u6B3E\u4E13\u4E3A\u9AD8\u7EA7\u673A\u5668\u4EBA\u5E94\u7528\u8BBE\u8BA1\u7684\u9AD8\u6027\u80FD\u8FB9\u7F18 AI \u8F7D\u677F\u3002\u5B83\u652F\u6301 NVIDIA Jetson Orin Nano \u548C Orin NX \u6A21\u5757\u7684 Super/MAXN \u6A21\u5F0F\uFF0C\u63D0\u4F9B\u9AD8\u8FBE 157 TOPS \u7684 AI \u8BA1\u7B97\u80FD\u529B\u3002\u8BE5\u8F7D\u677F\u63D0\u4F9B\u5E7F\u6CDB\u7684\u8FDE\u63A5\u9009\u9879\uFF0C\u5305\u62EC\u53CC\u5343\u5146\u4EE5\u592A\u7F51\u3001\u591A\u4E2A USB 3.2 \u7AEF\u53E3\u3001CAN\u3001\u7528\u4E8E 5G/Wi-Fi/BT \u6A21\u5757\u7684 M.2 \u63D2\u69FD\uFF0C\u4EE5\u53CA\u53EF\u9009\u7684 GMSL2 \u6444\u50CF\u5934\u652F\u6301\u3002\u9884\u88C5 JetPack 6\uFF0C\u786E\u4FDD\u673A\u5668\u4EBA\u5F00\u53D1\u7684\u65E0\u7F1D\u90E8\u7F72\u3002\u575A\u56FA\u7684\u8BBE\u8BA1\u652F\u6301\u5BBD\u5DE5\u4F5C\u6E29\u5EA6\u8303\u56F4\uFF0C\u5E76\u5305\u542B\u9884\u88C5\u7684\u6563\u70ED\u5668\u548C\u98CE\u6247\u3002\u8BBE\u7F6E\u8FC7\u7A0B\u5305\u62EC\u4F7F\u7528\u517C\u5BB9\u7684 Ubuntu \u4E3B\u673A PC \u5C06 JetPack \u64CD\u4F5C\u7CFB\u7EDF\u5237\u5199\u5230 NVMe SSD \u4E0A\uFF0C\u7136\u540E\u8FDB\u884C\u786C\u4EF6\u914D\u7F6E\u548C\u63A5\u53E3\u4F7F\u7528\u3002\u4E3A\u5F00\u53D1\u8005\u63D0\u4F9B\u8BE6\u7EC6\u7684\u786C\u4EF6\u89C4\u683C\u3001\u673A\u68B0\u56FE\u7EB8\u548C\u6280\u672F\u8D44\u6E90\uFF0C\u4EE5\u53CA\u7528\u4E8E\u6545\u969C\u6392\u9664\u548C\u8BA8\u8BBA\u7684\u793E\u533A\u548C\u6280\u672F\u652F\u6301\u6E20\u9053\u3002","permalink":"/cn/recomputer_robotics_j401_getting_started"},{"id":"zh-CN/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/cn_reComputer_Robotics_Hardware_Interfaces_Usage","title":"reComputer Robotics \u786C\u4EF6\u548C\u63A5\u53E3\u4F7F\u7528","description":"\u672Cwiki\u5168\u9762\u4ECB\u7ECD\u4E86reComputer Jetson Robotics J401\u8F7D\u677F\u7684\u786C\u4EF6\u7279\u6027\u548C\u63A5\u53E3\u4F7F\u7528\u65B9\u6CD5\u3002\u6DB5\u76D6\u8BE6\u7EC6\u89C4\u683C\u3001\u652F\u6301\u7684\u6A21\u5757\u3001\u8BBE\u7F6E\u8BF4\u660E\uFF0C\u4EE5\u53CA\u4F7F\u7528\u5404\u79CD\u63A5\u53E3\uFF08\u5982M.2\u3001\u4EE5\u592A\u7F51\u3001USB\u3001CAN\u3001UART\u3001I2C\u548CGMSL2\u76F8\u673A\u6269\u5C55\uFF09\u7684\u5B9E\u7528\u6307\u5357\uFF0C\u5E2E\u52A9\u7528\u6237\u5FEB\u901F\u5F00\u59CB\u5728J401\u5E73\u53F0\u4E0A\u8FDB\u884C\u673A\u5668\u4EBA\u5F00\u53D1\u3002","permalink":"/cn/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"ja/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/ja_reComputer_Robotics_Hardware_Interfaces_Usage","title":"reComputer Robotics\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u3068\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u4F7F\u7528\u65B9\u6CD5","description":"\u3053\u306Ewiki\u306F\u3001reComputer Jetson Robotics J401\u30AD\u30E3\u30EA\u30A2\u30DC\u30FC\u30C9\u306E\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u6A5F\u80FD\u3068\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u4F7F\u7528\u65B9\u6CD5\u306B\u3064\u3044\u3066\u5305\u62EC\u7684\u306B\u7D39\u4ECB\u3057\u307E\u3059\u3002\u8A73\u7D30\u306A\u4ED5\u69D8\u3001\u30B5\u30DD\u30FC\u30C8\u3055\u308C\u308B\u30E2\u30B8\u30E5\u30FC\u30EB\u3001\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u624B\u9806\u3001M.2\u3001Ethernet\u3001USB\u3001CAN\u3001UART\u3001I2C\u3001GMSL2\u30AB\u30E1\u30E9\u62E1\u5F35\u306A\u3069\u306E\u5404\u7A2E\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306E\u5B9F\u7528\u7684\u306A\u4F7F\u7528\u30AC\u30A4\u30C9\u3092\u7DB2\u7F85\u3057\u3001\u30E6\u30FC\u30B6\u30FC\u304CJ401\u30D7\u30E9\u30C3\u30C8\u30D5\u30A9\u30FC\u30E0\u3067\u306E\u30ED\u30DC\u30C6\u30A3\u30AF\u30B9\u958B\u767A\u3092\u8FC5\u901F\u306B\u958B\u59CB\u3067\u304D\u308B\u3088\u3046\u652F\u63F4\u3057\u307E\u3059\u3002","permalink":"/ja/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"ja/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/ja_reComputer_Robotics_Getting_Started","title":"reComputer Robotics\u3092\u59CB\u3081\u308B","description":"reComputer Robotics J401\u306F\u3001\u9AD8\u5EA6\u306A\u30ED\u30DC\u30C6\u30A3\u30AF\u30B9\u30A2\u30D7\u30EA\u30B1\u30FC\u30B7\u30E7\u30F3\u5411\u3051\u306B\u8A2D\u8A08\u3055\u308C\u305F\u9AD8\u6027\u80FD\u30A8\u30C3\u30B8AI\u30AD\u30E3\u30EA\u30A2\u30DC\u30FC\u30C9\u3067\u3059\u3002NVIDIA Jetson Orin Nano\u304A\u3088\u3073Orin NX\u30E2\u30B8\u30E5\u30FC\u30EB\u3092Super/MAXN\u30E2\u30FC\u30C9\u3067\u30B5\u30DD\u30FC\u30C8\u3057\u3001\u6700\u5927157 TOPS\u306EAI\u8A08\u7B97\u80FD\u529B\u3092\u63D0\u4F9B\u3057\u307E\u3059\u3002\u3053\u306E\u30DC\u30FC\u30C9\u306F\u3001\u30C7\u30E5\u30A2\u30EB\u30AE\u30AC\u30D3\u30C3\u30C8\u30A4\u30FC\u30B5\u30CD\u30C3\u30C8\u3001\u8907\u6570\u306EUSB 3.2\u30DD\u30FC\u30C8\u3001CAN\u30015G/Wi-Fi/BT\u30E2\u30B8\u30E5\u30FC\u30EB\u7528M.2\u30B9\u30ED\u30C3\u30C8\u3001\u30AA\u30D7\u30B7\u30E7\u30F3\u306EGMSL2\u30AB\u30E1\u30E9\u30B5\u30DD\u30FC\u30C8\u306A\u3069\u3001\u8C4A\u5BCC\u306A\u63A5\u7D9A\u30AA\u30D7\u30B7\u30E7\u30F3\u3092\u63D0\u4F9B\u3057\u307E\u3059\u3002JetPack 6\u304C\u30D7\u30EA\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u304A\u308A\u3001\u30ED\u30DC\u30C6\u30A3\u30AF\u30B9\u958B\u767A\u306E\u30B7\u30FC\u30E0\u30EC\u30B9\u306A\u5C55\u958B\u3092\u4FDD\u8A3C\u3057\u307E\u3059\u3002\u5805\u7262\u306A\u8A2D\u8A08\u306B\u3088\u308A\u5E83\u3044\u52D5\u4F5C\u6E29\u5EA6\u7BC4\u56F2\u3092\u30B5\u30DD\u30FC\u30C8\u3057\u3001\u30D5\u30A1\u30F3\u4ED8\u304D\u30D2\u30FC\u30C8\u30B7\u30F3\u30AF\u304C\u30D7\u30EA\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u307E\u3059\u3002\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u306B\u306F\u3001\u4E92\u63DB\u6027\u306E\u3042\u308BUbuntu\u30DB\u30B9\u30C8PC\u3092\u4F7F\u7528\u3057\u3066NVMe SSD\u306BJetPack OS\u3092\u30D5\u30E9\u30C3\u30B7\u30E5\u3057\u3001\u305D\u306E\u5F8C\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u69CB\u6210\u3068\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u4F7F\u7528\u3092\u884C\u3044\u307E\u3059\u3002\u958B\u767A\u8005\u5411\u3051\u306B\u8A73\u7D30\u306A\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u4ED5\u69D8\u3001\u6A5F\u68B0\u56F3\u9762\u3001\u6280\u8853\u30EA\u30BD\u30FC\u30B9\u304C\u63D0\u4F9B\u3055\u308C\u3001\u30C8\u30E9\u30D6\u30EB\u30B7\u30E5\u30FC\u30C6\u30A3\u30F3\u30B0\u3068\u8B70\u8AD6\u306E\u305F\u3081\u306E\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u304A\u3088\u3073\u6280\u8853\u30B5\u30DD\u30FC\u30C8\u30C1\u30E3\u30CD\u30EB\u3082\u7528\u610F\u3055\u308C\u3066\u3044\u307E\u3059\u3002","permalink":"/ja/recomputer_robotics_j401_getting_started"},{"id":"es/Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/es_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Uso de Interfaces","description":"Esta wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y uso de interfaces de la placa portadora reComputer Jetson Robotics J401. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, UART, I2C y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J401.","permalink":"/es/recomputer_jetson_robotics_j401_getting_started"},{"id":"ja/Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/ja_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u4F7F\u7528\u65B9\u6CD5","description":"\u3053\u306Ewiki\u306F\u3001reComputer Jetson Robotics J401\u30AD\u30E3\u30EA\u30A2\u30DC\u30FC\u30C9\u306E\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u6A5F\u80FD\u3068\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u4F7F\u7528\u65B9\u6CD5\u306B\u3064\u3044\u3066\u5305\u62EC\u7684\u306A\u7D39\u4ECB\u3092\u63D0\u4F9B\u3057\u307E\u3059\u3002\u8A73\u7D30\u306A\u4ED5\u69D8\u3001\u5BFE\u5FDC\u30E2\u30B8\u30E5\u30FC\u30EB\u3001\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u624B\u9806\u3001M.2\u3001Ethernet\u3001USB\u3001CAN\u3001UART\u3001I2C\u3001GMSL2\u30AB\u30E1\u30E9\u62E1\u5F35\u306A\u3069\u306E\u5404\u7A2E\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306E\u5B9F\u7528\u7684\u306A\u30AC\u30A4\u30C9\u3092\u7DB2\u7F85\u3057\u3001\u30E6\u30FC\u30B6\u30FC\u304CJ401\u30D7\u30E9\u30C3\u30C8\u30D5\u30A9\u30FC\u30E0\u3067\u306E\u30ED\u30DC\u30C6\u30A3\u30AF\u30B9\u958B\u767A\u3092\u8FC5\u901F\u306B\u958B\u59CB\u3067\u304D\u308B\u3088\u3046\u652F\u63F4\u3057\u307E\u3059\u3002","permalink":"/ja/recomputer_jetson_robotics_j401_getting_started"},{"id":"zh-CN/Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/cn_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"\u63A5\u53E3\u4F7F\u7528","description":"\u672C wiki \u63D0\u4F9B\u4E86 reComputer Jetson Robotics J401 \u8F7D\u677F\u7684\u786C\u4EF6\u7279\u6027\u548C\u63A5\u53E3\u4F7F\u7528\u7684\u5168\u9762\u4ECB\u7ECD\u3002\u6DB5\u76D6\u8BE6\u7EC6\u89C4\u683C\u3001\u652F\u6301\u7684\u6A21\u5757\u3001\u8BBE\u7F6E\u8BF4\u660E\uFF0C\u4EE5\u53CA\u4F7F\u7528\u5404\u79CD\u63A5\u53E3\uFF08\u5982 M.2\u3001\u4EE5\u592A\u7F51\u3001USB\u3001CAN\u3001UART\u3001I2C \u548C GMSL2 \u76F8\u673A\u6269\u5C55\uFF09\u7684\u5B9E\u7528\u6307\u5357\uFF0C\u5E2E\u52A9\u7528\u6237\u5FEB\u901F\u5F00\u59CB\u5728 J401 \u5E73\u53F0\u4E0A\u8FDB\u884C\u673A\u5668\u4EBA\u5F00\u53D1\u3002","permalink":"/cn/recomputer_jetson_robotics_j401_getting_started"}],"unlisted":false}}')}}]);